#include <bits/stdc++.h>
using namespace std;
// helper to fill a General
void t_fill(General &g, const string &name, const string &nation, int bday, int bmon, int byear, const string &ber, int dday, int dmon, int dyear, const string &der, const vector<string> &battles){
    g.name = name; g.nationality = nation;
    g.born = {bday,bmon,byear,ber};
    g.death = {dday,dmon,dyear,der};
    g.total_known_battles = (int)battles.size();
    if (!battles.empty()){
        g.known_battles = new string[battles.size()];
        for (size_t i=0;i<battles.size();++i) g.known_battles[i]=battles[i];
    } else g.known_battles = nullptr;
}
int main(){
    General* arr = new General[3];
    t_fill(arr[0],"A","X",1,1,1000,"AD",1,1,1050,"AD", {"B1","B2"});
    t_fill(arr[1],"B","Y",2,2,1010,"AD",2,2,1060,"AD", {"C1"});
    t_fill(arr[2],"C","Z",3,3,1020,"AD",3,3,1070,"AD", {});
    Node* head = prob2(arr,3);
    for(Node* cur=head;cur;cur=cur->next){
        cout << cur->general.name << "\n";
    }
    return 0;
}

